INSERT INTO members ("id","role","name","functionText","photo","position") VALUES (1,'Director(a)','Nombre pendiente','dirige el herbario, autoriza los servicios y representa a la colección ante la universidad.','',1);
INSERT INTO members ("id","role","name","functionText","photo","position") VALUES (2,'Curador(a)','Nombre pendiente','cuida la colección, verifica la identificación taxonómica y revisa los registros de los ejemplares.','',2);
INSERT INTO members ("id","role","name","functionText","photo","position") VALUES (3,'Auxiliar de colección','Nombre pendiente','prepara, seca, etiqueta y organiza el material botánico, y registra los datos de colecta.','',3);
INSERT INTO members ("id","role","name","functionText","photo","position") VALUES (4,'Investigadores y estudiantes','Nombres pendientes','realizan colectas y proyectos de investigación, y apoyan las actividades del herbario.','',4);
